(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-793":{scenario:{company:"Chuỗi nhà hàng Bếp Mộc Lan",supervisor:{name:"Tạ Bảo Ngân",role:{vi:"Giám đốc Ẩm thực",en:"Director of Food & Beverage"}},ref_code:"FB-4472",title:{vi:"Đúng dị ứng. Đúng giá vốn. An toàn thực phẩm trước tiên.",en:"Right allergens. Right food cost. Food safety first."},brief:{vi:"Bạn rà soát hồ sơ FB-4472 trước tiệc tối 120 khách: món gỏi cuốn ăn kèm sốt đậu phộng rang. Báo cáo tháng 10: tồn kho thực phẩm đầu kỳ 126 triệu đồng, nhập trong kỳ 512 triệu, tồn cuối kỳ 141 triệu, suất ăn nhân viên 18 triệu, doanh thu thức ăn chưa thuế 1580 triệu. Sửa nhóm chất gây dị ứng trên ma trận dị ứng và tỷ lệ giá vốn thực phẩm (làm tròn 1 chữ số thập phân), rồi lập báo cáo có căn cứ.",en:"You are reviewing file FB-4472 before a 120-guest dinner: fresh spring rolls served with roasted peanut sauce. October report: opening food inventory 126 million VND, purchases 512 million, closing inventory 141 million, staff meals 18 million, food revenue before tax 1580 million. Correct the allergen group on the allergen matrix and the food cost percentage (rounded to 1 decimal place), then write an evidence-based report."},reference_title:{vi:"Ma trận dị ứng & báo cáo giá vốn đã duyệt · FB-4472",en:"Approved allergen matrix & food cost report · FB-4472"},fields:[{id:"ALLERGEN",label:{vi:"Nhóm chất gây dị ứng của món",en:"Dish allergen group"},initial:"Tree nuts",expected:"Peanut",choices:["Tree nuts","Peanut","Sesame"],reference:"Ma trận chất gây dị ứng đã duyệt",hint:{vi:"Đậu phộng là cây họ đậu, được quản lý thành nhóm dị ứng riêng, không thuộc nhóm hạt cây như hạnh nhân, óc chó.",en:"Peanut is a legume and is managed as its own allergen group, not with tree nuts such as almonds or walnuts."}},{id:"FOOD_COST",label:{vi:"Tỷ lệ giá vốn thực phẩm (%)",en:"Food cost percentage (%)"},initial:"31.5",expected:"30.3",reference:"Báo cáo giá vốn tháng 10",ref_value:{vi:"Tồn đầu 126; nhập 512; tồn cuối 141; suất ăn nhân viên 18; doanh thu 1580 (triệu đồng)",en:"Opening 126; purchases 512; closing 141; staff meals 18; revenue 1580 (million VND)"},hint:{vi:"Suất ăn nhân viên không phải giá vốn món bán cho khách, phải trừ ra trước khi chia cho doanh thu.",en:"Staff meals are not the cost of food sold to guests and must be deducted before dividing by revenue."}}],sop32:{vi:"Giá vốn thực phẩm = tồn đầu kỳ + nhập trong kỳ - tồn cuối kỳ - suất ăn nhân viên; tỷ lệ giá vốn (%) = giá vốn / doanh thu thức ăn chưa thuế x 100, làm tròn 1 chữ số thập phân (mô phỏng).",en:"Cost of food sold = opening inventory + purchases - closing inventory - staff meals; food cost (%) = cost of food sold / food revenue before tax x 100, rounded to 1 decimal (training rule)."},context:{label:"POS & KHO / FB-4472",metrics:[{label:{vi:"Doanh thu thức ăn",en:"Food revenue"},value:"1,580 M VND"},{label:{vi:"Tồn đầu / tồn cuối",en:"Opening / closing stock"},value:"126 / 141 M VND"},{label:{vi:"Suất ăn nhân viên",en:"Staff meals"},value:"18 M VND"}]},crisis:{vi:"Đoàn tiệc có 1 khách dị ứng đậu phộng. Bếp trưởng nhắn: “Không kịp làm sốt riêng đâu, cứ dùng sốt chung, bảo phục vụ nói với khách là món này không có đậu phộng.”",en:"One dinner guest has a peanut allergy. The head chef messages you: “No time for a separate sauce. Use the shared one and tell the servers to say this dish has no peanuts.”"},options:{safe:{vi:"Không phục vụ món chứa đậu phộng và không nói sai với khách; báo Giám đốc Ẩm thực, chuẩn bị món thay thế an toàn bằng dụng cụ riêng và thông tin trung thực cho khách.",en:"Do not serve the peanut dish or mislead the guest; inform the F&B Director, prepare a safe alternative with separate utensils and tell the guest the truth."},shortcut:{vi:"Dùng sốt chung như bếp trưởng nói và dặn phục vụ trả lời là không có đậu phộng.",en:"Use the shared sauce as the chef says and tell servers to answer that there are no peanuts."},wait:{vi:"Không can thiệp, để phục vụ và bếp tự giải quyết khi khách hỏi.",en:"Do nothing and let servers and the kitchen deal with it if the guest asks."}},questions:{vi:["Vì sao bạn đổi nhóm chất gây dị ứng của món trên ma trận? Thành phần nào chứng minh lựa chọn đó?","Trình bày cách tính tỷ lệ giá vốn thực phẩm và cách xử lý khi bếp muốn che giấu thành phần gây dị ứng."],en:["Why did you change the dish's allergen group on the matrix? Which ingredient supports your choice?","Explain how you calculated the food cost percentage and how you handle a kitchen that wants to hide an allergen."]},hints:{vi:["Đọc công thức chuẩn của món và đối chiếu từng thành phần với danh sách nhóm dị ứng.","Theo SOP mục 3.2: tính giá vốn từ biến động tồn kho, trừ các khoản không bán cho khách.","Đọc lại SOP mục 4.2: thông tin dị ứng phải trung thực, không chắc chắn thì không phục vụ."],en:["Read the dish's standard recipe and check each ingredient against the allergen group list.","Per SOP 3.2: derive cost from inventory movement and deduct items not sold to guests.","Re-read SOP 4.2: allergen information must be truthful; if in doubt, do not serve."]}},learning:{summary:{vi:"Quản lý dịch vụ ẩm thực và nhà hàng điều hành toàn bộ hoạt động sảnh và phối hợp bếp: tiêu chuẩn phục vụ, xếp ca nhân sự, thực đơn, kiểm soát kho, giá vốn, doanh thu và an toàn thực phẩm. Người quản lý chịu trách nhiệm trải nghiệm của khách, quản lý chất gây dị ứng, tuân thủ HACCP và lợi nhuận của nhà hàng. Nghề đòi hỏi kỹ năng lãnh đạo đội ngũ, đọc số liệu kinh doanh và sự kiên quyết đặt an toàn của khách lên trên áp lực doanh thu.",en:"An F&B restaurant operations manager runs the dining room and coordinates with the kitchen: service standards, staff rostering, menus, stock control, food cost, revenue and food safety. The manager is responsible for the guest experience, allergen management, HACCP compliance and restaurant profit. The role requires team leadership, business numeracy and the firmness to put guest safety above sales pressure."},responsibilities:{vi:["Xếp ca, phân công khu vực phục vụ và huấn luyện tiêu chuẩn dịch vụ cho nhân viên.","Kiểm soát tồn kho, định mức công thức, giá vốn thực phẩm và đồ uống theo tháng.","Duy trì hồ sơ HACCP, kiểm tra nhiệt độ nhận hàng, bảo quản và lưu mẫu thức ăn.","Quản lý ma trận chất gây dị ứng và quy trình phục vụ khách có yêu cầu ăn uống đặc biệt.","Phân tích doanh thu, thực đơn, phản hồi của khách và đề xuất cải tiến."],en:["Roster staff, assign service sections and train service standards.","Control inventory, recipe specs and monthly food and beverage cost.","Keep HACCP records and check receiving temperatures, storage and food sample retention.","Manage the allergen matrix and the process for guests with special dietary needs.","Analyse sales, menu performance and guest feedback and propose improvements."]},competencies:[{name:{vi:"Kiểm soát giá vốn",en:"Cost control"},desc:{vi:"Tính đúng giá vốn từ biến động tồn kho, phát hiện hao hụt và điều chỉnh định mức.",en:"Compute cost from inventory movement, spot shrinkage and adjust recipe specs."}},{name:{vi:"An toàn thực phẩm",en:"Food safety"},desc:{vi:"Vận hành HACCP, kiểm soát nhiệt độ, lây nhiễm chéo và chất gây dị ứng.",en:"Run HACCP and control temperature, cross-contamination and allergens."}},{name:{vi:"Lãnh đạo đội ngũ",en:"Team leadership"},desc:{vi:"Xếp ca hợp lý, huấn luyện tại chỗ và giữ tinh thần đội trong giờ cao điểm.",en:"Roster smartly, coach on the floor and keep morale at peak times."}},{name:{vi:"Trải nghiệm khách",en:"Guest experience"},desc:{vi:"Xử lý phàn nàn tại chỗ, cá nhân hóa dịch vụ và theo dõi đánh giá trực tuyến.",en:"Resolve complaints on the spot, personalise service and track online reviews."}},{name:{vi:"Trung thực với khách",en:"Honesty with guests"},desc:{vi:"Cung cấp thông tin thành phần chính xác, từ chối che giấu dù bị áp lực về thời gian.",en:"Give accurate ingredient information and refuse to hide it under time pressure."}}],knowledge:{vi:["Luật An toàn thực phẩm số 55/2010/QH12 và Nghị định 15/2018/NĐ-CP hướng dẫn thi hành.","Nguyên tắc HACCP và ISO 22000:2018 về hệ thống quản lý an toàn thực phẩm.","Hướng dẫn của Bộ Y tế về kiểm thực ba bước và lưu mẫu thức ăn tại cơ sở kinh doanh ăn uống.","Quản lý chất gây dị ứng: nhóm chính như đậu phộng, hạt cây, sữa, trứng, cá, giáp xác, đậu nành, lúa mì.","Kỹ thuật thực đơn (menu engineering), giá vốn, năng suất lao động và báo cáo theo USALI."],en:["Food Safety Law No. 55/2010/QH12 and its implementing Decree 15/2018/ND-CP.","HACCP principles and ISO 22000:2018 on food safety management systems.","Ministry of Health guidance on three-step food checks and food sample retention in food service.","Allergen management: main groups such as peanut, tree nuts, milk, egg, fish, crustaceans, soy and wheat.","Menu engineering, food cost, labour productivity and USALI reporting."]},tools:["Phần mềm bán hàng nhà hàng (POS)","Phần mềm quản lý kho và công thức","Nhiệt kế đầu dò thực phẩm","Sổ theo dõi HACCP điện tử","Phần mềm xếp ca nhân viên"],kpis:{vi:["Tỷ lệ giá vốn thực phẩm so với mục tiêu ngân sách.","Giá trị hóa đơn bình quân mỗi khách.","Điểm hài lòng của khách và tỷ lệ phàn nàn trên 1000 lượt phục vụ.","Kết quả kiểm tra an toàn thực phẩm nội bộ không có lỗi nghiêm trọng."],en:["Food cost percentage against the budget target.","Average check per guest.","Guest satisfaction and complaints per 1000 covers.","Internal food safety audits with no critical findings."]},day:[{time:"09:00",vi:"Kiểm tra nhận hàng: đo nhiệt độ, hạn dùng, nguồn gốc và từ chối hàng không đạt.",en:"Check deliveries: temperature, use-by dates, origin, and reject non-compliant goods."},{time:"10:30",vi:"Họp ca, thông báo món đặc biệt, khách dị ứng và mục tiêu doanh thu trong ngày.",en:"Hold the pre-shift briefing on specials, allergy guests and today's sales target."},{time:"11:30",vi:"Điều phối phục vụ bữa trưa, theo dõi thời gian ra món và xử lý phản hồi khách.",en:"Run lunch service, watch ticket times and handle guest feedback."},{time:"15:00",vi:"Phân tích doanh thu, giá vốn, kiểm kê nhanh các mặt hàng giá trị cao.",en:"Analyse sales and food cost and spot-count high-value items."},{time:"17:30",vi:"Kiểm tra bố trí tiệc tối, xác nhận món thay thế cho khách có yêu cầu đặc biệt.",en:"Check the dinner banquet setup and confirm alternatives for special dietary guests."}],mistakes:{vi:["Gộp đậu phộng vào nhóm hạt cây trên ma trận dị ứng.","Quên trừ suất ăn nhân viên và hàng chuyển bộ phận khi tính giá vốn.","Nhận hàng tươi sống mà không đo nhiệt độ và không ghi sổ theo dõi."],en:["Grouping peanuts with tree nuts on the allergen matrix.","Forgetting to deduct staff meals and transfers when computing food cost.","Accepting fresh goods without checking temperature or logging it."]},career:[{vi:"Giám sát nhà hàng",en:"Restaurant supervisor"},{vi:"Trợ lý quản lý nhà hàng",en:"Assistant restaurant manager"},{vi:"Quản lý dịch vụ ẩm thực và nhà hàng",en:"F&B restaurant operations manager"},{vi:"Giám đốc Ẩm thực",en:"Director of food and beverage"}],glossary:[{term:"Food cost %",vi:"Tỷ lệ giá vốn thực phẩm trên doanh thu thức ăn, chỉ số cốt lõi về hiệu quả bếp.",en:"Cost of food sold as a share of food revenue, a core kitchen efficiency metric."},{term:"Cross-contact",vi:"Lây nhiễm chéo chất gây dị ứng từ món này sang món khác qua dụng cụ, bề mặt, dầu chiên.",en:"Transfer of an allergen from one food to another via utensils, surfaces or frying oil."},{term:"HACCP",vi:"Hệ thống phân tích mối nguy và điểm kiểm soát tới hạn trong sản xuất, chế biến thực phẩm.",en:"Hazard Analysis and Critical Control Points system for food production and handling."},{term:"Par level",vi:"Mức tồn kho chuẩn cần có cho mỗi mặt hàng giữa hai lần nhập.",en:"Standard stock level needed for each item between deliveries."},{term:"Average check",vi:"Giá trị hóa đơn bình quân mỗi khách, bằng doanh thu chia số lượt khách.",en:"Average spend per guest, equal to revenue divided by covers."}],quiz:[{q:{vi:"Tồn đầu 50, nhập 200, tồn cuối 40, suất ăn nhân viên 10, doanh thu thức ăn 600 (triệu đồng). Tỷ lệ giá vốn thực phẩm là bao nhiêu?",en:"Opening 50, purchases 200, closing 40, staff meals 10, food revenue 600 (million VND). What is the food cost percentage?"},options:{vi:["33.3%","35.0%","36.7%","41.7%"],en:["33.3%","35.0%","36.7%","41.7%"]},answer:0,explain:{vi:"Giá vốn = 50 + 200 - 40 - 10 = 200; tỷ lệ = 200 / 600 x 100 = 33.3%.",en:"Cost = 50 + 200 - 40 - 10 = 200; ratio = 200 / 600 x 100 = 33.3%."}},{q:{vi:"Trong HACCP, điểm kiểm soát tới hạn (CCP) là gì?",en:"In HACCP, what is a critical control point (CCP)?"},options:{vi:["Bất kỳ bước nào trong bếp","Nơi lưu hồ sơ kiểm tra","Bước có thể kiểm soát để ngăn ngừa, loại bỏ hoặc giảm mối nguy đến mức chấp nhận được","Khu vực cấm nhân viên lạ"],en:["Any step in the kitchen","Where inspection records are kept","A step where control can prevent, eliminate or reduce a hazard to an acceptable level","A staff-only area"]},answer:2,explain:{vi:"CCP là bước thiết yếu có giới hạn tới hạn, được giám sát để kiểm soát mối nguy an toàn thực phẩm.",en:"A CCP is an essential step with critical limits that is monitored to control a food safety hazard."}},{q:{vi:"Bếp muốn dùng sốt chung có đậu phộng cho khách dị ứng và bảo phục vụ nói là không có. Bạn làm gì?",en:"The kitchen wants to use a shared peanut sauce for an allergic guest and tell them it has none. What do you do?"},options:{vi:["Đồng ý vì lượng rất ít","Dừng món, báo quản lý cấp trên, làm món thay thế an toàn và nói thật với khách","Bỏ sốt ra khỏi đĩa rồi phục vụ","Để khách tự chọn món"],en:["Agree because the amount is tiny","Stop the dish, escalate, prepare a safe alternative and tell the guest the truth","Scrape off the sauce and serve","Let the guest choose on their own"]},answer:1,explain:{vi:"Một lượng rất nhỏ chất gây dị ứng cũng có thể gây sốc phản vệ; che giấu thông tin là vi phạm đạo đức và an toàn.",en:"Even a trace of an allergen can trigger anaphylaxis; hiding it breaches ethics and safety."}},{q:{vi:"Tôm đông lạnh giao đến đã rã đông mềm, nhiệt độ cao hơn tiêu chuẩn nhận hàng. Bạn xử lý thế nào?",en:"Frozen shrimp arrive soft and thawed, above the receiving temperature standard. What do you do?"},options:{vi:["Nhận rồi cấp đông lại ngay","Nhận và chế biến trong ngày","Nhận một nửa để thử","Từ chối nhận, ghi biên bản và báo nhà cung cấp"],en:["Accept and refreeze immediately","Accept and cook today","Accept half as a trial","Reject it, record it and notify the supplier"]},answer:3,explain:{vi:"Hàng không đạt nhiệt độ nhận là điểm kiểm soát an toàn; phải từ chối, lập biên bản và đánh giá lại nhà cung cấp.",en:"Receiving temperature is a safety control point; reject the goods, document it and review the supplier."}}],tools_en:["Restaurant point-of-sale software (POS)","Inventory and recipe management software","Food probe thermometer","Electronic HACCP log","Staff scheduling software"]}}})})(window.KKR);
